import{_ as s,I as a,o as n,c as l,b6 as e,J as r}from"./chunks/framework.BUXTSoD9.js";const f=JSON.parse('{"title":"Data Visualization and Dashboards","description":"","frontmatter":{},"headers":[],"relativePath":"en/appendix/5-data/data-visualization.md","filePath":"en/appendix/5-data/data-visualization.md"}'),d={name:"en/appendix/5-data/data-visualization.md"};function h(c,t,p,u,m,g){const i=a("ChartTypeSelectorDemo"),o=a("DashboardLayoutDemo");return n(),l("div",null,[t[0]||(t[0]=e('<h1 id="data-visualization-and-dashboards" tabindex="-1">Data Visualization and Dashboards <a class="header-anchor" href="#data-visualization-and-dashboards" aria-label="Permalink to “Data Visualization and Dashboards”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Preface</p><p><strong>A good chart is worth a thousand rows of data.</strong> Data visualization transforms abstract numbers into intuitive visual representations, allowing people to understand the story behind the data in seconds. From Excel charts to Grafana monitoring dashboards, visualization is everywhere.</p></div><p><strong>What will you learn in this article?</strong></p><p>After completing this chapter, you will gain:</p><ul><li><strong>Chart Selection</strong>: Choose the most appropriate chart type based on your data purpose</li><li><strong>Visualization Principles</strong>: Master the core design principles of data visualization</li><li><strong>Dashboard Design</strong>: Understand layout patterns for different types of dashboards</li><li><strong>Tool Ecosystem</strong>: Familiarize yourself with the positioning and selection of mainstream visualization tools</li><li><strong>Common Pitfalls</strong>: Avoid misleading charts and common visualization mistakes</li></ul><table tabindex="0"><thead><tr><th>Chapter</th><th>Content</th><th>Key Concepts</th></tr></thead><tbody><tr><td><strong>Chapter 1</strong></td><td>Chart Type Selection</td><td>Comparison, trends, proportions, distributions, relationships</td></tr><tr><td><strong>Chapter 2</strong></td><td>Visualization Design Principles</td><td>Data-ink ratio, consistency, readability</td></tr><tr><td><strong>Chapter 3</strong></td><td>Dashboard Layout</td><td>Overview, comparison, drill-down, real-time</td></tr><tr><td><strong>Chapter 4</strong></td><td>Tool Selection</td><td>ECharts, D3, Grafana, Metabase</td></tr><tr><td><strong>Chapter 5</strong></td><td>Common Pitfalls</td><td>Truncated axes, 3D pie charts, color misuse</td></tr></tbody></table><hr><h2 id="_0-the-big-picture-why-visualization-matters" tabindex="-1">0. The Big Picture: Why Visualization Matters <a class="header-anchor" href="#_0-the-big-picture-why-visualization-matters" aria-label="Permalink to “0. The Big Picture: Why Visualization Matters”">​</a></h2><p>The human brain processes visual information much faster than text. A line chart lets you quickly see that &quot;sales dropped last month,&quot; while the same information presented in a table might require row-by-row comparison to reach the same conclusion.</p><p>The core value of visualization:</p><ul><li><strong>Discover patterns</strong>: Trends, cycles, and outliers are immediately apparent in charts</li><li><strong>Support decision-making</strong>: Enable non-technical people to understand data and participate in decisions</li><li><strong>Communication efficiency</strong>: A picture is worth a thousand words, reducing ambiguity in data interpretation</li></ul><div class="tip custom-block"><p class="custom-block-title">Visualization ≠ Pretty</p><p>The goal of visualization is to <strong>convey information</strong>, not to show off. A plain but accurate bar chart is far more valuable than a flashy but hard-to-understand 3D chart.</p></div><hr><h2 id="_1-chart-type-selection-tell-the-right-story-with-the-right-chart" tabindex="-1">1. Chart Type Selection: Tell the Right Story with the Right Chart <a class="header-anchor" href="#_1-chart-type-selection-tell-the-right-story-with-the-right-chart" aria-label="Permalink to “1. Chart Type Selection: Tell the Right Story with the Right Chart”">​</a></h2><p>The first step in choosing a chart is not &quot;what chart do I like,&quot; but &quot;what information do I want to convey.&quot; Different data purposes correspond to different optimal chart types.</p>',15)),r(i),t[1]||(t[1]=e('<h3 id="chart-selection-quick-reference" tabindex="-1">Chart Selection Quick Reference <a class="header-anchor" href="#chart-selection-quick-reference" aria-label="Permalink to “Chart Selection Quick Reference”">​</a></h3><table tabindex="0"><thead><tr><th>Data Purpose</th><th>Recommended Chart</th><th>Not Recommended</th><th>Reason</th></tr></thead><tbody><tr><td>Compare magnitudes</td><td>Bar chart, Column chart</td><td>Pie chart</td><td>The human eye is more sensitive to length differences than angle differences</td></tr><tr><td>Show trends</td><td>Line chart, Area chart</td><td>Bar chart</td><td>The continuity of a line implies temporal continuity</td></tr><tr><td>Show proportions</td><td>Pie chart (≤5 categories), Stacked bar chart</td><td>3D pie chart</td><td>3D perspective distorts area proportions</td></tr><tr><td>Show distributions</td><td>Histogram, Box plot</td><td>Line chart</td><td>Distributions require viewing frequency, not trends</td></tr><tr><td>Show relationships</td><td>Scatter plot, Bubble chart</td><td>Bar chart</td><td>The relationship between two continuous variables requires two-dimensional space</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">A Simple Decision Rule</p><ul><li><strong>One variable</strong> → Histogram (distribution) or number card (KPI)</li><li><strong>Two variables</strong> → Line chart (time vs. value) or scatter plot (value vs. value)</li><li><strong>Multiple categories</strong> → Bar chart (comparison) or pie chart (proportion, ≤5 categories)</li><li><strong>Multiple dimensions</strong> → Radar chart or parallel coordinates plot</li></ul></div><hr><h2 id="_2-visualization-design-principles-let-the-data-speak" tabindex="-1">2. Visualization Design Principles: Let the Data Speak <a class="header-anchor" href="#_2-visualization-design-principles-let-the-data-speak" aria-label="Permalink to “2. Visualization Design Principles: Let the Data Speak”">​</a></h2><p>Good visualization is not about being &quot;pretty&quot; but about being &quot;understandable.&quot; Several classic principles proposed by Edward Tufte in <em>The Visual Display of Quantitative Information</em> remain important references for visualization design today.</p><table tabindex="0"><thead><tr><th>Principle</th><th>Description</th><th>Anti-pattern</th></tr></thead><tbody><tr><td>Data-ink ratio</td><td>The proportion of &quot;ink&quot; used to display data in a chart should be as high as possible</td><td>Excessive gridlines, decorative elements</td></tr><tr><td>Minimize non-data elements</td><td>Remove visual elements that convey no information</td><td>3D effects, shadows, gradient backgrounds</td></tr><tr><td>Consistent scale</td><td>Start axes from zero with uniform tick marks; if truncating an axis, clearly indicate it</td><td>Y-axis starting at 95 without explanation</td></tr><tr><td>Sensible color use</td><td>Use color to encode information, not for decoration</td><td>Rainbow colors for ordinal data</td></tr><tr><td>Clear labeling</td><td>Title, axis labels, legend, and units are all indispensable</td><td>No units, no time range</td></tr></tbody></table><h3 id="_2-1-data-ink-ratio" tabindex="-1">2.1 Data-Ink Ratio <a class="header-anchor" href="#_2-1-data-ink-ratio" aria-label="Permalink to “2.1 Data-Ink Ratio”">​</a></h3><blockquote><p>The proportion of &quot;ink&quot; used to express data in a chart relative to the total &quot;ink&quot; should be as high as possible.</p></blockquote><p>Simply put: <strong>remove everything that doesn&#39;t convey information</strong>.</p><table tabindex="0"><thead><tr><th>Should Remove</th><th>Should Keep</th></tr></thead><tbody><tr><td>3D effects, shadows, gradients</td><td>Data points, axis labels</td></tr><tr><td>Excessive gridlines</td><td>Key reference lines (e.g., target values)</td></tr><tr><td>Decorative icons</td><td>Legends (when there are multiple series)</td></tr><tr><td>Flashy background colors</td><td>Clear titles and units</td></tr></tbody></table><h3 id="_2-2-consistency-principle" tabindex="-1">2.2 Consistency Principle <a class="header-anchor" href="#_2-2-consistency-principle" aria-label="Permalink to “2.2 Consistency Principle”">​</a></h3><ul><li><strong>Color consistency</strong>: Use the same color for the same dimension across different charts, e.g., &quot;revenue&quot; is always blue</li><li><strong>Scale consistency</strong>: Axes should start from 0 whenever possible, unless there&#39;s a good reason and clear annotation</li><li><strong>Time consistency</strong>: Intervals on the time axis should be uniform; don&#39;t plot unevenly spaced time points as if they were evenly spaced</li></ul><h3 id="_2-3-readability-principle" tabindex="-1">2.3 Readability Principle <a class="header-anchor" href="#_2-3-readability-principle" aria-label="Permalink to “2.3 Readability Principle”">​</a></h3><ul><li><strong>Titles should state conclusions</strong>: Not &quot;Monthly Sales&quot; but &quot;Sales Have Declined for 3 Consecutive Months&quot;</li><li><strong>Annotate key points</strong>: Add annotations at outliers and inflection points to guide the reader&#39;s attention</li><li><strong>Control information density</strong>: Each chart should convey 1-2 core messages; don&#39;t cram too much in</li></ul><div class="tip custom-block"><p class="custom-block-title">Three Rules for Color Use</p><ol><li><strong>Same metric, same color</strong>: Revenue should always be blue across all charts, not sometimes blue and sometimes green</li><li><strong>Sequential data uses gradients</strong>: Temperature from low to high uses a blue→red gradient, not discrete colors</li><li><strong>Consider colorblind-friendliness</strong>: Approximately 8% of males have red-green color blindness; avoid relying solely on red and green to distinguish critical information</li></ol></div><hr><h2 id="_3-dashboard-layout-different-scenarios-different-patterns" tabindex="-1">3. Dashboard Layout: Different Scenarios, Different Patterns <a class="header-anchor" href="#_3-dashboard-layout-different-scenarios-different-patterns" aria-label="Permalink to “3. Dashboard Layout: Different Scenarios, Different Patterns”">​</a></h2><p>A dashboard is an organic combination of multiple charts. A good dashboard doesn&#39;t just pile charts together—it selects an appropriate layout pattern based on the use case.</p>',19)),r(o),t[2]||(t[2]=e('<h3 id="four-common-layout-patterns" tabindex="-1">Four Common Layout Patterns <a class="header-anchor" href="#four-common-layout-patterns" aria-label="Permalink to “Four Common Layout Patterns”">​</a></h3><table tabindex="0"><thead><tr><th>Layout Pattern</th><th>Core Structure</th><th>Use Case</th><th>Design Points</th></tr></thead><tbody><tr><td>Overview</td><td>KPI cards + trend charts + detail tables</td><td>Executive daily reports, operations dashboards</td><td>Place core metrics at the top; key numbers visible at a glance</td></tr><tr><td>Comparison analysis</td><td>Symmetric left-right layout</td><td>A/B testing, year-over-year analysis</td><td>Keep comparison dimensions consistent, highlight differences</td></tr><tr><td>Drill-down analysis</td><td>Progressive expansion from summary to detail</td><td>Sales analysis, user behavior analysis</td><td>Support click interactions, layer-by-layer exploration</td></tr><tr><td>Real-time monitoring</td><td>Large numbers + real-time curves + alert status</td><td>Double Eleven big screens, server monitoring</td><td>Auto-refresh, dark background, suitable for projection</td></tr></tbody></table><h3 id="_5-principles-of-dashboard-design" tabindex="-1">5 Principles of Dashboard Design <a class="header-anchor" href="#_5-principles-of-dashboard-design" aria-label="Permalink to “5 Principles of Dashboard Design”">​</a></h3><ol><li><strong>First ask &quot;who is looking&quot;</strong>: The CEO views strategic metrics, operations views process metrics, engineers view technical metrics</li><li><strong>5-second rule</strong>: Users should understand the dashboard&#39;s core information within 5 seconds</li><li><strong>Information hierarchy</strong>: Place the most important content in the upper-left, secondary content below</li><li><strong>Minimize scrolling</strong>: Display core content on one screen; avoid making users scroll to see critical data</li><li><strong>Whitespace</strong>: Don&#39;t fill every inch of space; appropriate whitespace makes the visual experience more comfortable</li></ol><div class="tip custom-block"><p class="custom-block-title">Dashboard vs. Report</p><ul><li><strong>Dashboard</strong>: Real-time/near-real-time, interactive, oriented toward monitoring and quick decision-making</li><li><strong>Report</strong>: Generated periodically (daily/weekly/monthly), static, oriented toward detailed analysis and archival</li></ul><p>These two are not replacements for each other but complements. Dashboards identify problems; reports analyze them in depth.</p></div><hr><h2 id="_4-tool-selection-from-code-libraries-to-bi-platforms" tabindex="-1">4. Tool Selection: From Code Libraries to BI Platforms <a class="header-anchor" href="#_4-tool-selection-from-code-libraries-to-bi-platforms" aria-label="Permalink to “4. Tool Selection: From Code Libraries to BI Platforms”">​</a></h2><p>Visualization tools can be divided into three tiers: code-level chart libraries, data analysis chart libraries, and BI platforms. Which one to choose depends on requirements complexity, interaction needs, and team technical capabilities.</p><h3 id="_4-1-code-level-chart-libraries" tabindex="-1">4.1 Code-Level Chart Libraries <a class="header-anchor" href="#_4-1-code-level-chart-libraries" aria-label="Permalink to “4.1 Code-Level Chart Libraries”">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Language/Platform</th><th>Features</th><th>Use Case</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>Ready to use, rich chart types, excellent documentation</td><td>Embedded charts in business systems</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>Low-level flexibility, can customize any visualization</td><td>Highly customized data visualization</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>Lightweight and simple, quick to get started</td><td>Simple chart requirements</td></tr><tr><td>Matplotlib</td><td>Python</td><td>Standard scientific computing library, static charts</td><td>Data analysis, paper figures</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>Interactive charts, 3D support</td><td>Data exploration, Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-bi-platforms-no-code-low-code" tabindex="-1">4.2 BI Platforms (No-Code / Low-Code) <a class="header-anchor" href="#_4-2-bi-platforms-no-code-low-code" aria-label="Permalink to “4.2 BI Platforms (No-Code / Low-Code)”">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Positioning</th><th>Core Strength</th><th>Suitable Team</th></tr></thead><tbody><tr><td>Grafana</td><td>Monitoring visualization</td><td>Strong time-series support, alerting integration</td><td>Ops/SRE teams</td></tr><tr><td>Metabase</td><td>Lightweight BI</td><td>Open source and free, create charts from SQL</td><td>Small to mid teams building quickly</td></tr><tr><td>Apache Superset</td><td>Enterprise BI</td><td>Open source, supports big data sources</td><td>Companies with data teams</td></tr><tr><td>Tableau</td><td>Commercial BI</td><td>Drag-and-drop, excellent visualization</td><td>Business analysts</td></tr><tr><td>Power BI</td><td>Commercial BI</td><td>Strong integration with Microsoft ecosystem</td><td>Enterprises using the Microsoft stack</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Selection Advice</p><ul><li><strong>Developers embedding charts in products</strong> → ECharts or Chart.js (for simple scenarios)</li><li><strong>Data analysts doing exploratory analysis</strong> → Plotly + Jupyter or Metabase</li><li><strong>Ops monitoring dashboards</strong> → Grafana (the de facto standard)</li><li><strong>Business teams doing self-service analytics</strong> → Metabase (open source) or Tableau (commercial)</li><li><strong>Need high customization</strong> → D3.js (steep learning curve, but most flexible)</li></ul></div><hr><h2 id="_5-common-pitfalls-these-charts-are-lying-to-you" tabindex="-1">5. Common Pitfalls: These Charts Are Lying to You <a class="header-anchor" href="#_5-common-pitfalls-these-charts-are-lying-to-you" aria-label="Permalink to “5. Common Pitfalls: These Charts Are Lying to You”">​</a></h2><p>Data visualization is a double-edged sword: used well, it reveals truth; used poorly, it creates illusions. Below are the most common visualization pitfalls that every data practitioner should be able to recognize.</p><h3 id="_5-1-truncated-axes" tabindex="-1">5.1 Truncated Axes <a class="header-anchor" href="#_5-1-truncated-axes" aria-label="Permalink to “5.1 Truncated Axes”">​</a></h3><p>Changing the Y-axis starting point from 0 to a large number makes tiny differences look like massive changes.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Actual Difference</th><th>Visual Perception</th></tr></thead><tbody><tr><td>Y-axis starts at 0</td><td>Product A: 98 points, Product B: 95 points</td><td>Small gap</td></tr><tr><td>Y-axis starts at 90</td><td>Same data</td><td>A appears to be several times larger than B</td></tr></tbody></table><p><strong>When is truncation acceptable?</strong> When absolute values are large but changes are small (e.g., stock price from 100 to 105), truncation is reasonable, but it must be clearly labeled.</p><h3 id="_5-2-the-3d-pie-chart-perspective-trap" tabindex="-1">5.2 The 3D Pie Chart Perspective Trap <a class="header-anchor" href="#_5-2-the-3d-pie-chart-perspective-trap" aria-label="Permalink to “5.2 The 3D Pie Chart Perspective Trap”">​</a></h3><p>3D perspective makes sectors closer to the viewer appear larger. A 25% sector can look like 35% under a 3D viewing angle.</p><p><strong>Solution</strong>: Never use 3D pie charts. Use regular pie charts or donut charts, or simply use bar charts.</p><h3 id="_5-3-color-misuse" tabindex="-1">5.3 Color Misuse <a class="header-anchor" href="#_5-3-color-misuse" aria-label="Permalink to “5.3 Color Misuse”">​</a></h3><table tabindex="0"><thead><tr><th>Wrong Practice</th><th>Correct Practice</th></tr></thead><tbody><tr><td>Using red-green to represent data</td><td>Using blue-orange and other colorblind-safe palettes</td></tr><tr><td>Different colors for each category</td><td>Using shades of the same color family for the same series</td></tr><tr><td>Encoding continuous data with color but no legend</td><td>Always provide a color legend and value labels</td></tr><tr><td>Insufficient contrast between background and data colors</td><td>Ensure WCAG AA level contrast</td></tr></tbody></table><h3 id="_5-4-other-common-mistakes" tabindex="-1">5.4 Other Common Mistakes <a class="header-anchor" href="#_5-4-other-common-mistakes" aria-label="Permalink to “5.4 Other Common Mistakes”">​</a></h3><table tabindex="0"><thead><tr><th>Pitfall</th><th>Problem</th><th>Fix</th></tr></thead><tbody><tr><td>Dual Y-axes</td><td>Two unrelated metrics sharing the X-axis implies causation</td><td>Split into two charts, or explicitly state no causal relationship</td></tr><tr><td>Area misrepresentation</td><td>Using a circle&#39;s radius instead of area to represent values</td><td>When values double, area should double, not radius</td></tr><tr><td>Uneven time axis</td><td>January, March, and December spaced equally</td><td>Arrange by actual time proportions</td></tr><tr><td>Too many categories</td><td>Pie chart with 15 sectors</td><td>Use bar charts for more than 5 categories, or group into &quot;Other&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Ethical Guidelines for Visualization</p><p>The purpose of visualization is to <strong>aid understanding</strong>, not to <strong>manipulate perception</strong>. Ask yourself every time you create a chart:</p><ul><li>If I were the reader, would this chart lead me to a wrong conclusion?</li><li>Am I hiding unfavorable data?</li><li>Are the axes, scales, and colors presenting the data fairly?</li></ul></div><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Data visualization is the &quot;last mile&quot; of delivering data value. No matter how good the analysis is, if it cannot be correctly understood, it&#39;s as if the analysis never happened.</p><p>Let&#39;s review the key takeaways from this chapter:</p><ol><li><strong>Choose the right chart</strong>: Select chart types based on data purpose (comparison, trends, proportions, distributions, relationships)</li><li><strong>Design principles</strong>: High data-ink ratio, consistency, and readability are the three core principles</li><li><strong>Dashboard layout</strong>: Overview, comparison, drill-down, and real-time patterns cover most scenarios</li><li><strong>Tool selection</strong>: From ECharts to Grafana, choose based on team capability and requirements complexity</li><li><strong>Avoid pitfalls</strong>: Truncated axes, 3D pie charts, and color misuse are the most common misleading techniques</li></ol><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Edward Tufte&#39;s visualization classic</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">ECharts Official Documentation</a> - The most popular charting library</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - Powerful low-level visualization library</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - The de facto standard for monitoring visualization</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - Chart type selection decision tree</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - Colorblind-safe color scheme tool</li></ul>',35))])}const y=s(d,[["render",h]]);export{f as __pageData,y as default};
